import java.io.*;
import java.util.*;
import java.lang.reflect.*;
import java.util.concurrent.*;

public class MessageQueueConsumer {

    enum Role { ADMIN, OPERATOR, VIEWER }

    private static final Map<String, Role> userRoles = new ConcurrentHashMap<>();
    private static final Map<String, List<String>> rolePermissions = new HashMap<>();
    private static final BlockingQueue<Message> messageQueue = new LinkedBlockingQueue<>();

    static {
        rolePermissions.put("ADMIN", Arrays.asList("execute", "configure", "read", "write"));
        rolePermissions.put("OPERATOR", Arrays.asList("configure", "read", "write"));
        rolePermissions.put("VIEWER", Arrays.asList("read"));
        userRoles.put("system", Role.ADMIN);
        userRoles.put("operator1", Role.OPERATOR);
        userRoles.put("guest", Role.VIEWER);
    }

    static class Message implements Serializable {
        private static final long serialVersionUID = 1L;
        String sender;
        String action;
        Map<String, Object> payload;
        long timestamp;

        Message(String sender, String action, Map<String, Object> payload) {
            this.sender = sender;
            this.action = action;
            this.payload = payload;
            this.timestamp = System.currentTimeMillis();
        }
    }

    static class AccessControlChecker {
        public boolean hasPermission(String user, String action) {
            Role role = userRoles.getOrDefault(user, Role.VIEWER);
            List<String> perms = rolePermissions.getOrDefault(role.name(), Collections.emptyList());
            return perms.contains(action);
        }

        public boolean validateMessageIntegrity(Message msg) {
            if (msg == null || msg.sender == null || msg.action == null) return false;
            if (msg.timestamp > System.currentTimeMillis() + 30000) return false;
            if (msg.timestamp < System.currentTimeMillis() - 300000) return false;
            return true;
        }
    }

    static class MessageHandler {
        private final AccessControlChecker acl = new AccessControlChecker();

        public Object processMessage(Message msg) throws Exception {
            if (!acl.validateMessageIntegrity(msg)) {
                throw new SecurityException("Message integrity check failed");
            }
            if (!acl.hasPermission(msg.sender, msg.action)) {
                throw new SecurityException("Access denied for " + msg.sender + " action: " + msg.action);
            }
            return dispatchAction(msg);
        }

        private Object dispatchAction(Message msg) throws Exception {
            switch (msg.action) {
                case "read":
                    return handleRead(msg.payload);
                case "write":
                    return handleWrite(msg.payload);
                case "configure":
                    return handleConfigure(msg.payload);
                case "execute":
                    return handleExecute(msg.payload);
                default:
                    throw new IllegalArgumentException("Unknown action: " + msg.action);
            }
        }

        private Object handleRead(Map<String, Object> payload) {
            String key = (String) payload.getOrDefault("key", "");
            return System.getProperty(key, "undefined");
        }

        private Object handleWrite(Map<String, Object> payload) {
            String key = (String) payload.get("key");
            String value = (String) payload.get("value");
            if (key != null && value != null && !key.startsWith("java.")) {
                System.setProperty(key, value);
                return "OK";
            }
            return "DENIED";
        }

        private Object handleConfigure(Map<String, Object> payload) {
            String targetUser = (String) payload.get("user");
            String newRole = (String) payload.get("role");
            if (targetUser != null && newRole != null) {
                try {
                    Role role = Role.valueOf(newRole.toUpperCase());
                    userRoles.put(targetUser, role);
                    return "Role updated";
                } catch (IllegalArgumentException e) {
                    return "Invalid role";
                }
            }
            return "Missing parameters";
        }

        private Object handleExecute(Map<String, Object> payload) throws Exception {
            String className = (String) payload.get("class");
            String methodName = (String) payload.get("method");
            Object[] args = (Object[]) payload.getOrDefault("args", new Object[0]);

            if (className == null || methodName == null) {
                throw new IllegalArgumentException("class and method required");
            }

            // Security: only allow classes in our approved namespace
            if (!isApprovedClass(className)) {
                throw new SecurityException("Class not in approved namespace: " + className);
            }

            Class<?> clazz = Class.forName(className);
            Method[] methods = clazz.getMethods();
            for (Method m : methods) {
                if (m.getName().equals(methodName) && m.getParameterCount() == args.length) {
                    if (Modifier.isStatic(m.getModifiers())) {
                        return m.invoke(null, args);
                    } else {
                        Object instance = clazz.getDeclaredConstructor().newInstance();
                        return m.invoke(instance, args);
                    }
                }
            }
            throw new NoSuchMethodException(methodName);
        }

        private boolean isApprovedClass(String className) {
            // Approved namespaces for execution
            String[] approved = {
                "com.company.tasks.",
                "com.company.utils.",
                "java.lang.",
                "java.util."
            };
            for (String prefix : approved) {
                if (className.startsWith(prefix)) {
                    return true;
                }
            }
            return false;
        }
    }

    static class ConsumerWorker implements Runnable {
        private final MessageHandler handler = new MessageHandler();
        private volatile boolean running = true;

        @Override
        public void run() {
            while (running) {
                try {
                    Message msg = messageQueue.poll(1, TimeUnit.SECONDS);
                    if (msg != null) {
                        try {
                            Object result = handler.processMessage(msg);
                            System.out.println("[OK] " + msg.action + " -> " + result);
                        } catch (SecurityException e) {
                            System.out.println("[DENIED] " + e.getMessage());
                        } catch (Exception e) {
                            System.out.println("[ERROR] " + e.getMessage());
                        }
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    running = false;
                }
            }
        }

        public void stop() { running = false; }
    }

    public static void enqueue(String sender, String action, Map<String, Object> payload) {
        messageQueue.offer(new Message(sender, action, payload));
    }

    public static void main(String[] args) throws Exception {
        ConsumerWorker worker = new ConsumerWorker();
        Thread t = new Thread(worker);
        t.start();

        // Simulate messages
        enqueue("guest", "read", Map.of("key", "os.name"));
        enqueue("operator1", "configure", Map.of("user", "guest", "role", "OPERATOR"));
        enqueue("system", "execute", Map.of("class", "java.lang.Runtime", "method", "exec", "args", new Object[]{"id"}));

        Thread.sleep(3000);
        worker.stop();
        t.join();
    }
}
